const hasCustomerPurchasedProduct = `-- name: HasCustomerPurchasedProduct :one

SELECT EXISTS (
    SELECT 1
    FROM order_lines ol
    JOIN orders o ON o.id = ol.order_id
    WHERE o.customer_id = $1
      AND o.status IN ('confirmed', 'fulfilled')
      AND ol.product_sku = (SELECT sku FROM catalog_products p WHERE p.id = $2)
) AS purchased
`

type HasCustomerPurchasedProductParams struct {
	CustomerID uuid.NullUUID `json:"customer_id"`
	ID         uuid.UUID     `json:"id"`
}

// ==================== Verified-purchase check ====================
// HasCustomerPurchasedProduct: returns 1 row if the customer has at
// least one confirmed/fulfilled order line for the product's SKU,
// 0 rows otherwise - used at review submission to set is_verified_purchase
// and to gate the customerCanReview eligibility resolver
func (q *Queries) HasCustomerPurchasedProduct(ctx context.Context, arg HasCustomerPurchasedProductParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, hasCustomerPurchasedProduct, arg.CustomerID, arg.ID)
	var purchased bool
	err := row.Scan(&purchased)
	return purchased, err
}

