const listReviewsForModeration = `-- name: ListReviewsForModeration :many
SELECT id, product_id, customer_id, channel_id, locale, title, body, is_verified_purchase, status, submitted_at, moderated_at, moderated_by, moderator_note, guest_name, guest_email, moderation_label, moderation_reason, moderation_checked_at, merchant_reply, merchant_reply_at, merchant_reply_by, moderation_tags, category_slugs FROM reviews
WHERE
    ($3::text[] IS NULL
     OR status = ANY($3::text[]))
AND ($4::uuid IS NULL
     OR product_id = $4::uuid)
AND ($5::uuid[] IS NULL
     OR channel_id = ANY($5::uuid[]))
AND ($6::text[] IS NULL
     OR jsonb_exists_any(category_slugs, $6::text[]))
ORDER BY submitted_at DESC
LIMIT $1 OFFSET $2
`

type ListReviewsForModerationParams struct {
	Limit         int32         `json:"limit"`
	Offset        int32         `json:"offset"`
	StatusFilter  []string      `json:"status_filter"`
	ProductID     uuid.NullUUID `json:"product_id"`
	ChannelIds    []uuid.UUID   `json:"channel_ids"`
	CategorySlugs []string      `json:"category_slugs"`
}

// ListReviewsForModeration returns reviews filterable by status,
// product, and channel - ORDER BY submitted_at DESC puts the newest
// pending review at the top of the moderation queue - the channel_ids
// narg scopes the page to the admin's permitted channels so pagination
// + total stay correct (a NULL array no-ops the filter for bypass
// admins, exactly like status_filter)
func (q *Queries) ListReviewsForModeration(ctx context.Context, arg ListReviewsForModerationParams) ([]Review, error) {
	rows, err := q.db.QueryContext(ctx, listReviewsForModeration,
		arg.Limit,
		arg.Offset,
		pq.Array(arg.StatusFilter),
		arg.ProductID,
		pq.Array(arg.ChannelIds),
		pq.Array(arg.CategorySlugs),
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Review{}
	for rows.Next() {
		var i Review
		if err := rows.Scan(
			&i.ID,
			&i.ProductID,
			&i.CustomerID,
			&i.ChannelID,
			&i.Locale,
			&i.Title,
			&i.Body,
			&i.IsVerifiedPurchase,
			&i.Status,
			&i.SubmittedAt,
			&i.ModeratedAt,
			&i.ModeratedBy,
			&i.ModeratorNote,
			&i.GuestName,
			&i.GuestEmail,
			&i.ModerationLabel,
			&i.ModerationReason,
			&i.ModerationCheckedAt,
			&i.MerchantReply,
			&i.MerchantReplyAt,
			&i.MerchantReplyBy,
			&i.ModerationTags,
			&i.CategorySlugs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

